export function tr(locale, text) {
  const progress = /^Question (\d+) of (\d+)$/.exec(text);
  if (progress) return (messages[locale]?.["Question {n} of {total}"] || text).replace("{n}", progress[1]).replace("{total}", progress[2]);
  return messages[locale]?.[text] || text;
}

export function languageName(code) {
  return ({en:"English",hi:"Hindi",ta:"Tamil",te:"Telugu",ml:"Malayalam"})[code] || code;
}
